pub mod bn254;
use crate::{runtime::is_unconstrained, static_assert};
use bn254::lt as bn254_lt;

impl Field {
    /// Asserts that `self` can be represented in `bit_size` bits.
    ///
    /// `BIT_SIZE` must be less than the number of bits in the field modulus.
    ///
    /// Example:
    ///
    /// ```noir
    /// let x: Field = 255;
    /// x.assert_max_bit_size::<8>();
    /// ```
    ///
    /// # Failures
    /// Causes a constraint failure for `Field` values exceeding `2^{bit_size}`.
    ///
    /// ```noir should_fail
    /// let x: Field = 256;
    /// // Fails: 256 needs 9 bits.
    /// x.assert_max_bit_size::<8>();
    /// ```
    // docs:start:assert_max_bit_size
    pub fn assert_max_bit_size<let BIT_SIZE: u32>(self) {
        // docs:end:assert_max_bit_size
        static_assert(
            BIT_SIZE < modulus_num_bits() as u32,
            "BIT_SIZE must be less than modulus_num_bits",
        );
        __assert_max_bit_size(self, BIT_SIZE);
    }

    /// Decomposes `self` into its little endian bit decomposition as a `[bool; N]` array.
    /// This array will be zero padded should not all bits be necessary to represent `self`.
    ///
    /// Example:
    ///
    /// ```noir
    /// let bits: [bool; 8] = 2.to_le_bits();
    /// assert_eq(bits, [false, true, false, false, false, false, false, false]);
    /// ```
    ///
    /// # Failures
    /// Causes a constraint failure for `Field` values exceeding `2^N` as the resulting array will not
    /// be able to represent the original `Field`.
    ///
    /// # Safety
    /// The bit decomposition returned is canonical and is guaranteed to not overflow the modulus.
    // docs:start:to_le_bits
    pub fn to_le_bits<let N: u32>(self: Self) -> [bool; N] {
        // docs:end:to_le_bits
        let bits = __to_le_bits(self);

        if !is_unconstrained() {
            // Ensure that the byte decomposition does not overflow the modulus
            let p = modulus_le_bits();
            assert(bits.len() <= p.len());
            let mut ok = bits.len() != p.len();
            for i in 0..N {
                if !ok {
                    if (bits[N - 1 - i] != p[N - 1 - i]) {
                        assert(p[N - 1 - i]);
                        ok = true;
                    }
                }
            }
            assert(ok);
        }
        bits
    }

    /// Decomposes `self` into its big endian bit decomposition as a `[bool; N]` array.
    /// This array will be zero padded should not all bits be necessary to represent `self`.
    ///
    /// Example:
    ///
    /// ```noir
    /// let bits: [bool; 8] = 2.to_be_bits();
    /// assert_eq(bits, [false, false, false, false, false, false, true, false]);
    /// ```
    ///
    /// # Failures
    /// Causes a constraint failure for `Field` values exceeding `2^N` as the resulting array will not
    /// be able to represent the original `Field`.
    ///
    /// # Safety
    /// The bit decomposition returned is canonical and is guaranteed to not overflow the modulus.
    // docs:start:to_be_bits
    pub fn to_be_bits<let N: u32>(self: Self) -> [bool; N] {
        // docs:end:to_be_bits
        let bits = __to_be_bits(self);

        if !is_unconstrained() {
            // Ensure that the decomposition does not overflow the modulus
            let p = modulus_be_bits();
            assert(bits.len() <= p.len());
            let mut ok = bits.len() != p.len();
            for i in 0..N {
                if !ok {
                    if (bits[i] != p[i]) {
                        assert(p[i]);
                        ok = true;
                    }
                }
            }
            assert(ok);
        }
        bits
    }

    /// Decomposes `self` into its little endian byte decomposition as a `[u8;N]` array
    /// This array will be zero padded should not all bytes be necessary to represent `self`.
    ///
    /// Example:
    ///
    /// ```noir
    /// let bytes: [u8; 4] = 0x01020304.to_le_bytes();
    /// assert_eq(bytes, [4, 3, 2, 1]);
    /// ```
    ///
    /// # Failures
    ///  The length N of the array must be big enough to contain all the bytes of the 'self',
    ///  and no more than the number of bytes required to represent the field modulus
    ///
    /// # Safety
    /// The result is ensured to be the canonical decomposition of the field element
    // docs:start:to_le_bytes
    pub fn to_le_bytes<let N: u32>(self: Self) -> [u8; N] {
        // docs:end:to_le_bytes
        static_assert(
            N <= modulus_le_bytes().len(),
            "N must be less than or equal to modulus_le_bytes().len()",
        );
        // Compute the byte decomposition
        let bytes = self.to_le_radix(256);

        if !is_unconstrained() {
            // Ensure that the byte decomposition does not overflow the modulus
            let p = modulus_le_bytes();
            assert(bytes.len() <= p.len());
            let mut ok = bytes.len() != p.len();
            for i in 0..N {
                if !ok {
                    if (bytes[N - 1 - i] != p[N - 1 - i]) {
                        assert(bytes[N - 1 - i] < p[N - 1 - i]);
                        ok = true;
                    }
                }
            }
            assert(ok);
        }
        bytes
    }

    /// Decomposes `self` into its big endian byte decomposition as a `[u8;N]` array of length required to represent the field modulus
    /// This array will be zero padded should not all bytes be necessary to represent `self`.
    ///
    /// Example:
    ///
    /// ```noir
    /// let bytes: [u8; 4] = 0x01020304.to_be_bytes();
    /// assert_eq(bytes, [1, 2, 3, 4]);
    /// ```
    ///
    /// # Failures
    ///  The length N of the array must be big enough to contain all the bytes of the 'self',
    ///  and no more than the number of bytes required to represent the field modulus
    ///
    /// # Safety
    /// The result is ensured to be the canonical decomposition of the field element
    // docs:start:to_be_bytes
    pub fn to_be_bytes<let N: u32>(self: Self) -> [u8; N] {
        // docs:end:to_be_bytes
        static_assert(
            N <= modulus_le_bytes().len(),
            "N must be less than or equal to modulus_le_bytes().len()",
        );
        // Compute the byte decomposition
        let bytes = self.to_be_radix(256);

        if !is_unconstrained() {
            // Ensure that the byte decomposition does not overflow the modulus
            let p = modulus_be_bytes();
            assert(bytes.len() <= p.len());
            let mut ok = bytes.len() != p.len();
            for i in 0..N {
                if !ok {
                    if (bytes[i] != p[i]) {
                        assert(bytes[i] < p[i]);
                        ok = true;
                    }
                }
            }
            assert(ok);
        }
        bytes
    }

    fn to_le_radix<let N: u32>(self: Self, radix: u32) -> [u8; N] {
        // Brillig does not need an immediate radix
        if !crate::runtime::is_unconstrained() {
            static_assert(1 < radix, "radix must be greater than 1");
            static_assert(radix <= 256, "radix must be less than or equal to 256");
            static_assert(radix & (radix - 1) == 0, "radix must be a power of 2");
        }
        __to_le_radix(self, radix)
    }

    fn to_be_radix<let N: u32>(self: Self, radix: u32) -> [u8; N] {
        // Brillig does not need an immediate radix
        if !crate::runtime::is_unconstrained() {
            static_assert(1 < radix, "radix must be greater than 1");
            static_assert(radix <= 256, "radix must be less than or equal to 256");
            static_assert(radix & (radix - 1) == 0, "radix must be a power of 2");
        }
        __to_be_radix(self, radix)
    }

    /// Returns `self` raised to the power `exponent`.
    ///
    /// `exponent` must be less than `2^32`. The power is computed by square-and-multiply over the
    /// exponent's 32 bits, so the circuit size doesn't depend on the value of `exponent`.
    ///
    /// Example:
    ///
    /// ```noir
    /// assert_eq(2.pow_32(10), 1024);
    /// ```
    ///
    /// # Failures
    ///
    /// Fails if `exponent` is `2^32` or more.
    pub fn pow_32(self, exponent: Field) -> Field {
        let mut r: Field = 1;
        let b: [bool; 32] = exponent.to_le_bits();

        for i in 1..33 {
            r *= r;
            r = (b[32 - i] as Field) * (r * self) + (1 - b[32 - i] as Field) * r;
        }
        r
    }

    /// Returns `true` if `self`, as an integer in `0..p`, is odd.
    ///
    /// This is the `sgn0` function used by hash-to-curve standards. Because `p` is odd, `-x` and
    /// `x` have different parities for every nonzero `x`.
    ///
    /// Example:
    ///
    /// ```noir
    /// assert(3.sgn0());
    /// assert(!4.sgn0());
    /// // -1 is p - 1, which is even.
    /// assert(!(-1).sgn0());
    /// ```
    pub fn sgn0(self) -> bool {
        (self as u8) % 2 == 1
    }

    /// Returns `true` if `self` is less than `another`, comparing them as integers in `0..p`.
    ///
    /// `Field` supports `==` and `!=`, but not the ordering operators `<`, `<=`, `>` and `>=`, and
    /// doesn't implement [`crate::cmp::Ord`]; this is how to order field elements. For `a > b`,
    /// use `b.lt(a)`. The result is fully constrained. Field arithmetic wraps around, so `-1` is
    /// the largest field element.
    ///
    /// Example:
    ///
    /// ```noir
    /// assert(1.lt(2));
    /// assert(!2.lt(2));
    /// assert(!(-1).lt(1));
    /// ```
    pub fn lt(self, another: Field) -> bool {
        if crate::compat::is_bn254() {
            bn254_lt(self, another)
        } else {
            lt_fallback(self, another)
        }
    }

    /// Convert a little endian byte array to a field element.
    /// If the provided byte array overflows the field modulus then the Field will silently wrap around.
    ///
    /// Example:
    ///
    /// ```noir
    /// assert_eq(Field::from_le_bytes([4, 3, 2, 1]), 0x01020304);
    /// ```
    ///
    /// # Failures
    /// `N` must be no greater than the number of bytes required to represent the field modulus
    // docs:start:from_le_bytes
    pub fn from_le_bytes<let N: u32>(bytes: [u8; N]) -> Field {
        // docs:end:from_le_bytes
        static_assert(
            N <= modulus_le_bytes().len(),
            "N must be less than or equal to modulus_le_bytes().len()",
        );
        let mut v = 1;
        let mut result = 0;

        for i in 0..N {
            result += (bytes[i] as Field) * v;
            v = v * 256;
        }
        result
    }

    /// Convert a big endian byte array to a field element.
    /// If the provided byte array overflows the field modulus then the Field will silently wrap around.
    ///
    /// Example:
    ///
    /// ```noir
    /// assert_eq(Field::from_be_bytes([1, 2, 3, 4]), 0x01020304);
    /// ```
    ///
    /// # Failures
    /// `N` must be no greater than the number of bytes required to represent the field modulus
    // docs:start:from_be_bytes
    pub fn from_be_bytes<let N: u32>(bytes: [u8; N]) -> Field {
        // docs:end:from_be_bytes
        static_assert(
            N <= modulus_be_bytes().len(),
            "N must be less than or equal to modulus_be_bytes().len()",
        );
        let mut v = 1;
        let mut result = 0;

        for i in 0..N {
            result += (bytes[N - 1 - i] as Field) * v;
            v = v * 256;
        }
        result
    }

    /// Convert a little endian byte array to a field element, asserting that the input is a
    /// canonical representation (strictly less than the field modulus).
    ///
    /// Example:
    ///
    /// ```noir
    /// assert_eq(Field::from_le_bytes_checked([4, 3, 2, 1]), 0x01020304);
    /// ```
    ///
    /// # Failures
    /// Causes a constraint failure if `bytes` encodes a value greater than or equal to the
    /// field modulus.
    // docs:start:from_le_bytes_checked
    pub fn from_le_bytes_checked<let N: u32>(bytes: [u8; N]) -> Field {
        // docs:end:from_le_bytes_checked
        let p = modulus_le_bytes();
        let mut ok = N != p.len();
        for i in 0..N {
            if !ok {
                if bytes[N - 1 - i] != p[N - 1 - i] {
                    assert(
                        bytes[N - 1 - i] < p[N - 1 - i],
                        "input bytes are not a canonical field representation",
                    );
                    ok = true;
                }
            }
        }
        assert(ok, "input bytes are not a canonical field representation");
        Field::from_le_bytes(bytes)
    }

    /// Convert a big endian byte array to a field element, asserting that the input is a
    /// canonical representation (strictly less than the field modulus).
    ///
    /// Example:
    ///
    /// ```noir
    /// assert_eq(Field::from_be_bytes_checked([1, 2, 3, 4]), 0x01020304);
    /// ```
    ///
    /// # Failures
    /// Causes a constraint failure if `bytes` encodes a value greater than or equal to the
    /// field modulus.
    // docs:start:from_be_bytes_checked
    pub fn from_be_bytes_checked<let N: u32>(bytes: [u8; N]) -> Field {
        // docs:end:from_be_bytes_checked
        let p = modulus_be_bytes();
        let mut ok = N != p.len();
        for i in 0..N {
            if !ok {
                if bytes[i] != p[i] {
                    assert(bytes[i] < p[i], "input bytes are not a canonical field representation");
                    ok = true;
                }
            }
        }
        assert(ok, "input bytes are not a canonical field representation");
        Field::from_be_bytes(bytes)
    }
}

#[builtin(apply_range_constraint)]
fn __assert_max_bit_size(value: Field, bit_size: u32) {}

// `_radix` must be less than 256
#[builtin(to_le_radix)]
fn __to_le_radix<let N: u32>(value: Field, radix: u32) -> [u8; N] {}

// `_radix` must be less than 256
#[builtin(to_be_radix)]
fn __to_be_radix<let N: u32>(value: Field, radix: u32) -> [u8; N] {}

/// Decomposes `self` into its little endian bit decomposition as a `[bool; N]` array.
/// This array will be zero padded should not all bits be necessary to represent `self`.
///
/// # Failures
/// Causes a constraint failure for [`Field`] values exceeding `2^N` as the resulting array will not
/// be able to represent the original `Field`.
///
/// # Safety
/// Values of `N` equal to or greater than the number of bits necessary to represent the `Field` modulus
/// (e.g. 254 for the BN254 field) allow for multiple bit decompositions. This is due to how the `Field` will
/// wrap around due to overflow when verifying the decomposition.
#[builtin(to_le_bits)]
fn __to_le_bits<let N: u32>(value: Field) -> [bool; N] {}

/// Decomposes `self` into its big endian bit decomposition as a `[bool; N]` array.
/// This array will be zero padded should not all bits be necessary to represent `self`.
///
/// # Failures
/// Causes a constraint failure for [`Field`] values exceeding `2^N` as the resulting array will not
/// be able to represent the original `Field`.
///
/// # Safety
/// Values of `N` equal to or greater than the number of bits necessary to represent the `Field` modulus
/// (e.g. 254 for the BN254 field) allow for multiple bit decompositions. This is due to how the `Field` will
/// wrap around due to overflow when verifying the decomposition.
#[builtin(to_be_bits)]
fn __to_be_bits<let N: u32>(value: Field) -> [bool; N] {}

/// Returns the number of bits in the field modulus: 254 for BN254.
///
/// This is a `comptime` function: the value is computed at compile time for the field being
/// compiled for. The example shows the values for BN254.
///
/// Example:
///
/// ```noir
/// assert_eq(std::field::modulus_num_bits(), 254);
/// ```
#[builtin(modulus_num_bits)]
pub comptime fn modulus_num_bits() -> u64 {}

/// Returns the bits of the field modulus, most significant first, without leading zeros.
///
/// This is a `comptime` function: the value is computed at compile time for the field being
/// compiled for. The example shows the values for BN254.
///
/// Example:
///
/// ```noir
/// let bits = std::field::modulus_be_bits();
/// assert_eq(bits.len(), 254);
/// assert(bits[0]);
/// ```
#[builtin(modulus_be_bits)]
pub comptime fn modulus_be_bits() -> [bool] {}

/// Returns the bits of the field modulus, least significant first, without leading zeros.
///
/// This is a `comptime` function: the value is computed at compile time for the field being
/// compiled for. The example shows the values for BN254.
///
/// Example:
///
/// ```noir
/// let bits = std::field::modulus_le_bits();
/// assert_eq(bits.len(), 254);
/// // The modulus is odd.
/// assert(bits[0]);
/// ```
#[builtin(modulus_le_bits)]
pub comptime fn modulus_le_bits() -> [bool] {}

/// Returns the bytes of the field modulus, most significant first.
///
/// This is a `comptime` function: the value is computed at compile time for the field being
/// compiled for. The example shows the values for BN254.
///
/// Example:
///
/// ```noir
/// let bytes = std::field::modulus_be_bytes();
/// assert_eq(bytes.len(), 32);
/// assert_eq(bytes[0], 0x30);
/// ```
#[builtin(modulus_be_bytes)]
pub comptime fn modulus_be_bytes() -> [u8] {}

/// Returns the bytes of the field modulus, least significant first.
///
/// This is a `comptime` function: the value is computed at compile time for the field being
/// compiled for. The example shows the values for BN254.
///
/// Example:
///
/// ```noir
/// let bytes = std::field::modulus_le_bytes();
/// assert_eq(bytes.len(), 32);
/// assert_eq(bytes[0], 0x01);
/// ```
#[builtin(modulus_le_bytes)]
pub comptime fn modulus_le_bytes() -> [u8] {}

/// An unconstrained only built in to efficiently compare fields.
#[builtin(field_less_than)]
unconstrained fn __field_less_than(x: Field, y: Field) -> bool {}

pub(crate) unconstrained fn field_less_than(x: Field, y: Field) -> bool {
    __field_less_than(x, y)
}

fn lt_fallback(x: Field, y: Field) -> bool {
    if is_unconstrained() {
        // Safety: unconstrained context
        unsafe {
            field_less_than(x, y)
        }
    } else {
        let x_bytes: [u8; 32] = x.to_le_bytes();
        let y_bytes: [u8; 32] = y.to_le_bytes();
        let mut x_is_lt = false;
        let mut done = false;
        for i in 0..32 {
            if (!done) {
                let x_byte = x_bytes[32 - 1 - i] as u8;
                let y_byte = y_bytes[32 - 1 - i] as u8;
                let bytes_match = x_byte == y_byte;
                if !bytes_match {
                    x_is_lt = x_byte < y_byte;
                    done = true;
                }
            }
        }
        x_is_lt
    }
}

mod tests {
    use crate::{panic::panic, runtime, static_assert};
    use super::{
        field_less_than, modulus_be_bits, modulus_be_bytes, modulus_le_bits, modulus_le_bytes,
    };

    #[test]
    // docs:start:to_be_bits_example
    fn test_to_be_bits() {
        let field = 2;
        let bits: [bool; 8] = field.to_be_bits();
        assert_eq(bits, [false, false, false, false, false, false, true, false]);
    }
    // docs:end:to_be_bits_example

    #[test]
    // docs:start:to_le_bits_example
    fn test_to_le_bits() {
        let field = 2;
        let bits: [bool; 8] = field.to_le_bits();
        assert_eq(bits, [false, true, false, false, false, false, false, false]);
    }
    // docs:end:to_le_bits_example

    #[test]
    // docs:start:to_be_bytes_example
    fn test_to_be_bytes() {
        let field = 2;
        let bytes: [u8; 8] = field.to_be_bytes();
        assert_eq(bytes, [0, 0, 0, 0, 0, 0, 0, 2]);
        assert_eq(Field::from_be_bytes::<8>(bytes), field);
    }
    // docs:end:to_be_bytes_example

    #[test]
    // docs:start:to_le_bytes_example
    fn test_to_le_bytes() {
        let field = 2;
        let bytes: [u8; 8] = field.to_le_bytes();
        assert_eq(bytes, [2, 0, 0, 0, 0, 0, 0, 0]);
        assert_eq(Field::from_le_bytes::<8>(bytes), field);
    }
    // docs:end:to_le_bytes_example

    #[test]
    // docs:start:to_be_radix_example
    fn test_to_be_radix() {
        // 259, in base 256, big endian, is [1, 3].
        // i.e. 3 * 256^0 + 1 * 256^1
        let field = 259;

        // The radix (in this example, 256) must be a power of 2.
        // The length of the returned byte array can be specified to be
        // >= the amount of space needed.
        let bytes: [u8; 8] = field.to_be_radix(256);
        assert_eq(bytes, [0, 0, 0, 0, 0, 0, 1, 3]);
        assert_eq(Field::from_be_bytes::<8>(bytes), field);
    }
    // docs:end:to_be_radix_example

    #[test]
    // docs:start:to_le_radix_example
    fn test_to_le_radix() {
        // 259, in base 256, little endian, is [3, 1].
        // i.e. 3 * 256^0 + 1 * 256^1
        let field = 259;

        // The radix (in this example, 256) must be a power of 2.
        // The length of the returned byte array can be specified to be
        // >= the amount of space needed.
        let bytes: [u8; 8] = field.to_le_radix(256);
        assert_eq(bytes, [3, 1, 0, 0, 0, 0, 0, 0]);
        assert_eq(Field::from_le_bytes::<8>(bytes), field);
    }
    // docs:end:to_le_radix_example

    #[test(should_fail_with = "radix must be greater than 1")]
    fn test_to_le_radix_1() {
        // this test should only fail in constrained mode
        if !runtime::is_unconstrained() {
            let field = 2;
            let _: [u8; 8] = field.to_le_radix(1);
        } else {
            panic("radix must be greater than 1");
        }
    }

    // Updated test to account for Brillig restriction that radix must be greater than 2
    #[test(should_fail_with = "radix must be greater than 1")]
    fn test_to_le_radix_brillig_1() {
        // this test should only fail in constrained mode
        if !runtime::is_unconstrained() {
            let field = 1;
            let _: [u8; 8] = field.to_le_radix(1);
        } else {
            panic("radix must be greater than 1");
        }
    }

    #[test(should_fail_with = "radix must be a power of 2")]
    fn test_to_le_radix_3() {
        // this test should only fail in constrained mode
        if !runtime::is_unconstrained() {
            let field = 2;
            let _: [u8; 8] = field.to_le_radix(3);
        } else {
            panic("radix must be a power of 2");
        }
    }

    #[test]
    fn test_to_le_radix_brillig_3() {
        // this test should only fail in constrained mode
        if runtime::is_unconstrained() {
            let field = 1;
            let out: [u8; 8] = field.to_le_radix(3);
            let mut expected = [0; 8];
            expected[0] = 1;
            assert(out == expected, "unexpected result");
        }
    }

    #[test(should_fail_with = "radix must be less than or equal to 256")]
    fn test_to_le_radix_512() {
        // this test should only fail in constrained mode
        if !runtime::is_unconstrained() {
            let field = 2;
            let _: [u8; 8] = field.to_le_radix(512);
        } else {
            panic("radix must be less than or equal to 256")
        }
    }

    #[test(should_fail_with = "Field failed to decompose into specified 16 limbs")]
    unconstrained fn not_enough_limbs_brillig() {
        let _: [u8; 16] = 0x100000000000000000000000000000000.to_le_bytes();
    }

    #[test(should_fail_with = "Field failed to decompose into specified 16 limbs")]
    fn not_enough_limbs() {
        let _: [u8; 16] = 0x100000000000000000000000000000000.to_le_bytes();
    }

    #[test(should_fail_with = "Field failed to decompose into specified 0 limbs")]
    unconstrained fn non_zero_field_to_le_bytes_zero_limbs() {
        let _: [u8; 0] = 5.to_le_bytes();
    }

    #[test(should_fail_with = "Field failed to decompose into specified 0 limbs")]
    unconstrained fn non_zero_field_to_be_bytes_zero_limbs() {
        let _: [u8; 0] = 5.to_be_bytes();
    }

    #[test]
    unconstrained fn zero_field_to_bytes_zero_limbs_unconstrained() {
        assert_eq((0 as Field).to_le_bytes::<0>().len(), 0);
        assert_eq((0 as Field).to_be_bytes::<0>().len(), 0);
        assert_eq((0 as Field).to_le_bits::<0>().len(), 0);
        assert_eq((0 as Field).to_be_bits::<0>().len(), 0);
    }

    #[test]
    fn zero_field_to_bytes_zero_limbs_constrained() {
        assert_eq((0 as Field).to_le_bytes::<0>().len(), 0);
        assert_eq((0 as Field).to_be_bytes::<0>().len(), 0);
        assert_eq((0 as Field).to_le_bits::<0>().len(), 0);
        assert_eq((0 as Field).to_be_bits::<0>().len(), 0);
    }

    #[test]
    fn zero_field_to_bytes_zero_limbs_comptime() {
        let _: [u8; 0] = comptime { (0 as Field).to_le_bytes() };
        let _: [u8; 0] = comptime { (0 as Field).to_be_bytes() };
        let _: [bool; 0] = comptime { (0 as Field).to_le_bits() };
        let _: [bool; 0] = comptime { (0 as Field).to_be_bits() };
    }

    #[test]
    unconstrained fn test_field_less_than() {
        assert(field_less_than(0, 1));
        assert(field_less_than(0, 0x100));
        assert(field_less_than(0x100, 0 - 1));
        assert(!field_less_than(0 - 1, 0));
    }

    #[test]
    unconstrained fn test_large_field_values_unconstrained() {
        let large_field = 0xffffffffffffffff;

        let bits: [bool; 64] = large_field.to_le_bits();
        assert_eq(bits[0], true);

        let bytes: [u8; 8] = large_field.to_le_bytes();
        assert_eq(Field::from_le_bytes::<8>(bytes), large_field);

        let radix_bytes: [u8; 8] = large_field.to_le_radix(256);
        assert_eq(Field::from_le_bytes::<8>(radix_bytes), large_field);
    }

    #[test]
    fn test_large_field_values() {
        let large_val = 0xffffffffffffffff;

        let bits: [bool; 64] = large_val.to_le_bits();
        assert_eq(bits[0], true);

        let bytes: [u8; 8] = large_val.to_le_bytes();
        assert_eq(Field::from_le_bytes::<8>(bytes), large_val);

        let radix_bytes: [u8; 8] = large_val.to_le_radix(256);
        assert_eq(Field::from_le_bytes::<8>(radix_bytes), large_val);
    }

    #[test]
    fn test_decomposition_edge_cases() {
        let zero_bits: [bool; 8] = 0.to_le_bits();
        assert_eq(zero_bits, [false; 8]);

        let zero_bytes: [u8; 8] = 0.to_le_bytes();
        assert_eq(zero_bytes, [0; 8]);

        let one_bits: [bool; 8] = 1.to_le_bits();
        let expected: [bool; 8] = [true, false, false, false, false, false, false, false];
        assert_eq(one_bits, expected);

        let pow2_bits: [bool; 8] = 4.to_le_bits();
        let expected: [bool; 8] = [false, false, true, false, false, false, false, false];
        assert_eq(pow2_bits, expected);
    }

    #[test]
    fn test_pow_32() {
        assert_eq(2.pow_32(3), 8);
        assert_eq(3.pow_32(2), 9);
        assert_eq(5.pow_32(0), 1);
        assert_eq(7.pow_32(1), 7);

        assert_eq(2.pow_32(10), 1024);

        assert_eq(0.pow_32(5), 0);
        assert_eq(0.pow_32(0), 1);

        assert_eq(1.pow_32(100), 1);
    }

    #[test]
    fn test_sgn0() {
        assert_eq(0.sgn0(), false);
        assert_eq(2.sgn0(), false);
        assert_eq(4.sgn0(), false);
        assert_eq(100.sgn0(), false);

        assert_eq(1.sgn0(), true);
        assert_eq(3.sgn0(), true);
        assert_eq(5.sgn0(), true);
        assert_eq(101.sgn0(), true);
    }

    #[test(should_fail_with = "Field failed to decompose into specified 8 limbs")]
    fn test_bit_decomposition_overflow() {
        // 8 bits can't represent large field values
        let large_val = 0x1000000000000000;
        let _: [bool; 8] = large_val.to_le_bits();
    }

    #[test(should_fail_with = "Field failed to decompose into specified 4 limbs")]
    fn test_byte_decomposition_overflow() {
        // 4 bytes can't represent large field values
        let large_val = 0x1000000000000000;
        let _: [u8; 4] = large_val.to_le_bytes();
    }

    #[test]
    fn test_to_from_be_bytes_bn254_edge_cases() {
        if crate::compat::is_bn254() {
            // checking that decrementing this byte produces the expected 32 BE bytes for (modulus - 1)
            let mut p_minus_1_bytes: [u8; 32] = modulus_be_bytes().as_array();
            assert(p_minus_1_bytes[32 - 1] > 0);
            p_minus_1_bytes[32 - 1] -= 1;

            let p_minus_1 = Field::from_be_bytes::<32>(p_minus_1_bytes);
            assert_eq(p_minus_1 + 1, 0);

            // checking that converting (modulus - 1) from and then to 32 BE bytes produces the same bytes
            let p_minus_1_converted_bytes: [u8; 32] = p_minus_1.to_be_bytes();
            assert_eq(p_minus_1_converted_bytes, p_minus_1_bytes);

            // checking that incrementing this byte produces 32 BE bytes for (modulus + 1)
            let mut p_plus_1_bytes: [u8; 32] = modulus_be_bytes().as_array();
            assert(p_plus_1_bytes[32 - 1] < 255);
            p_plus_1_bytes[32 - 1] += 1;

            let p_plus_1 = Field::from_be_bytes::<32>(p_plus_1_bytes);
            assert_eq(p_plus_1, 1);

            // checking that converting p_plus_1 to 32 BE bytes produces the same
            // byte set to 1 as p_plus_1_bytes and otherwise zeroes
            let mut p_plus_1_converted_bytes: [u8; 32] = p_plus_1.to_be_bytes();
            assert_eq(p_plus_1_converted_bytes[32 - 1], 1);
            p_plus_1_converted_bytes[32 - 1] = 0;
            assert_eq(p_plus_1_converted_bytes, [0; 32]);

            // checking that Field::from_be_bytes::<32> on the Field modulus produces 0
            assert_eq(modulus_be_bytes().len(), 32);
            let p = Field::from_be_bytes::<32>(modulus_be_bytes().as_array());
            assert_eq(p, 0);

            // checking that converting 0 to 32 BE bytes produces 32 zeroes
            let p_bytes: [u8; 32] = 0.to_be_bytes();
            assert_eq(p_bytes, [0; 32]);
        }
    }

    #[test]
    fn test_to_from_le_bytes_bn254_edge_cases() {
        if crate::compat::is_bn254() {
            // checking that decrementing this byte produces the expected 32 LE bytes for (modulus - 1)
            let mut p_minus_1_bytes: [u8; 32] = modulus_le_bytes().as_array();
            assert(p_minus_1_bytes[0] > 0);
            p_minus_1_bytes[0] -= 1;

            let p_minus_1 = Field::from_le_bytes::<32>(p_minus_1_bytes);
            assert_eq(p_minus_1 + 1, 0);

            // checking that converting (modulus - 1) from and then to 32 BE bytes produces the same bytes
            let p_minus_1_converted_bytes: [u8; 32] = p_minus_1.to_le_bytes();
            assert_eq(p_minus_1_converted_bytes, p_minus_1_bytes);

            // checking that incrementing this byte produces 32 LE bytes for (modulus + 1)
            let mut p_plus_1_bytes: [u8; 32] = modulus_le_bytes().as_array();
            assert(p_plus_1_bytes[0] < 255);
            p_plus_1_bytes[0] += 1;

            let p_plus_1 = Field::from_le_bytes::<32>(p_plus_1_bytes);
            assert_eq(p_plus_1, 1);

            // checking that converting p_plus_1 to 32 LE bytes produces the same
            // byte set to 1 as p_plus_1_bytes and otherwise zeroes
            let mut p_plus_1_converted_bytes: [u8; 32] = p_plus_1.to_le_bytes();
            assert_eq(p_plus_1_converted_bytes[0], 1);
            p_plus_1_converted_bytes[0] = 0;
            assert_eq(p_plus_1_converted_bytes, [0; 32]);

            // checking that Field::from_le_bytes::<32> on the Field modulus produces 0
            assert_eq(modulus_le_bytes().len(), 32);
            let p = Field::from_le_bytes::<32>(modulus_le_bytes().as_array());
            assert_eq(p, 0);

            // checking that converting 0 to 32 LE bytes produces 32 zeroes
            let p_bytes: [u8; 32] = 0.to_le_bytes();
            assert_eq(p_bytes, [0; 32]);
        }
    }

    #[test]
    fn test_from_le_bytes_checked_accepts_modulus_minus_one() {
        if crate::compat::is_bn254() {
            let mut p_minus_1_bytes: [u8; 32] = modulus_le_bytes().as_array();
            assert(p_minus_1_bytes[0] > 0);
            p_minus_1_bytes[0] -= 1;
            let p_minus_1 = Field::from_le_bytes_checked::<32>(p_minus_1_bytes);
            assert_eq(p_minus_1 + 1, 0);
        }
    }

    #[test(should_fail_with = "input bytes are not a canonical field representation")]
    fn test_from_le_bytes_checked_rejects_modulus() {
        if crate::compat::is_bn254() {
            let _ = Field::from_le_bytes_checked::<32>(modulus_le_bytes().as_array());
        } else {
            panic("input bytes are not a canonical field representation");
        }
    }

    #[test(should_fail_with = "input bytes are not a canonical field representation")]
    fn test_from_le_bytes_checked_rejects_modulus_plus_one() {
        if crate::compat::is_bn254() {
            let mut p_plus_1_bytes: [u8; 32] = modulus_le_bytes().as_array();
            assert(p_plus_1_bytes[0] < 255);
            p_plus_1_bytes[0] += 1;
            let _ = Field::from_le_bytes_checked::<32>(p_plus_1_bytes);
        } else {
            panic("input bytes are not a canonical field representation");
        }
    }

    #[test]
    fn test_from_be_bytes_checked_accepts_modulus_minus_one() {
        if crate::compat::is_bn254() {
            let mut p_minus_1_bytes: [u8; 32] = modulus_be_bytes().as_array();
            assert(p_minus_1_bytes[32 - 1] > 0);
            p_minus_1_bytes[32 - 1] -= 1;
            let p_minus_1 = Field::from_be_bytes_checked::<32>(p_minus_1_bytes);
            assert_eq(p_minus_1 + 1, 0);
        }
    }

    #[test(should_fail_with = "input bytes are not a canonical field representation")]
    fn test_from_be_bytes_checked_rejects_modulus() {
        if crate::compat::is_bn254() {
            let _ = Field::from_be_bytes_checked::<32>(modulus_be_bytes().as_array());
        } else {
            panic("input bytes are not a canonical field representation");
        }
    }

    #[test(should_fail_with = "input bytes are not a canonical field representation")]
    fn test_from_be_bytes_checked_rejects_modulus_plus_one() {
        if crate::compat::is_bn254() {
            let mut p_plus_1_bytes: [u8; 32] = modulus_be_bytes().as_array();
            assert(p_plus_1_bytes[32 - 1] < 255);
            p_plus_1_bytes[32 - 1] += 1;
            let _ = Field::from_be_bytes_checked::<32>(p_plus_1_bytes);
        } else {
            panic("input bytes are not a canonical field representation");
        }
    }

    #[test]
    fn test_from_bytes_checked_small_n() {
        // For N < modulus_bytes().len(), the input cannot overflow the modulus, so the checked
        // variants behave identically to the unchecked ones.
        let le_bytes: [u8; 8] = [3, 1, 0, 0, 0, 0, 0, 0];
        assert_eq(Field::from_le_bytes_checked::<8>(le_bytes), 259);
        let be_bytes: [u8; 8] = [0, 0, 0, 0, 0, 0, 1, 3];
        assert_eq(Field::from_be_bytes_checked::<8>(be_bytes), 259);
    }

    /// Convert a little endian bit array to a field element.
    /// If the provided bit array overflows the field modulus then the Field will silently wrap around.
    fn from_le_bits<let N: u32>(bits: [bool; N]) -> Field {
        static_assert(
            N <= modulus_le_bits().len(),
            "N must be less than or equal to modulus_le_bits().len()",
        );
        let mut v = 1;
        let mut result = 0;

        for i in 0..N {
            result += (bits[i] as Field) * v;
            v = v * 2;
        }
        result
    }

    /// Convert a big endian bit array to a field element.
    /// If the provided bit array overflows the field modulus then the Field will silently wrap around.
    fn from_be_bits<let N: u32>(bits: [bool; N]) -> Field {
        let mut v = 1;
        let mut result = 0;

        for i in 0..N {
            result += (bits[N - 1 - i] as Field) * v;
            v = v * 2;
        }
        result
    }

    #[test]
    fn test_to_from_be_bits_bn254_edge_cases() {
        if crate::compat::is_bn254() {
            // checking that decrementing this bit produces the expected 254 BE bits for (modulus - 1)
            let mut p_minus_1_bits: [bool; 254] = modulus_be_bits().as_array();
            assert(p_minus_1_bits[254 - 1]);
            p_minus_1_bits[254 - 1] = false;

            let p_minus_1 = from_be_bits::<254>(p_minus_1_bits);
            assert_eq(p_minus_1 + 1, 0);

            // checking that converting (modulus - 1) from and then to 254 BE bits produces the same bits
            let p_minus_1_converted_bits: [bool; 254] = p_minus_1.to_be_bits();
            assert_eq(p_minus_1_converted_bits, p_minus_1_bits);

            // checking that incrementing this bit produces 254 BE bits for (modulus + 4)
            let mut p_plus_4_bits: [bool; 254] = modulus_be_bits().as_array();
            assert(!p_plus_4_bits[254 - 3]);
            p_plus_4_bits[254 - 3] = true;

            let p_plus_4 = from_be_bits::<254>(p_plus_4_bits);
            assert_eq(p_plus_4, 4);

            // checking that converting p_plus_4 to 254 BE bits produces the same
            // bit set to 1 as p_plus_4_bits and otherwise zeroes
            let mut p_plus_4_converted_bits: [bool; 254] = p_plus_4.to_be_bits();
            assert(p_plus_4_converted_bits[254 - 3]);
            p_plus_4_converted_bits[254 - 3] = false;
            assert_eq(p_plus_4_converted_bits, [false; 254]);

            // checking that Field::from_be_bits::<254> on the Field modulus produces 0
            assert_eq(modulus_be_bits().len(), 254);
            let p = from_be_bits::<254>(modulus_be_bits().as_array());
            assert_eq(p, 0);

            // checking that converting 0 to 254 BE bits produces 254 false values
            let p_bits: [bool; 254] = 0.to_be_bits();
            assert_eq(p_bits, [false; 254]);
        }
    }

    #[test]
    fn test_to_from_le_bits_bn254_edge_cases() {
        if crate::compat::is_bn254() {
            // checking that decrementing this bit produces the expected 254 LE bits for (modulus - 1)
            let mut p_minus_1_bits: [bool; 254] = modulus_le_bits().as_array();
            assert(p_minus_1_bits[0]);
            p_minus_1_bits[0] = false;

            let p_minus_1 = from_le_bits::<254>(p_minus_1_bits);
            assert_eq(p_minus_1 + 1, 0);

            // checking that converting (modulus - 1) from and then to 254 BE bits produces the same bits
            let p_minus_1_converted_bits: [bool; 254] = p_minus_1.to_le_bits();
            assert_eq(p_minus_1_converted_bits, p_minus_1_bits);

            // checking that incrementing this bit produces 254 LE bits for (modulus + 4)
            let mut p_plus_4_bits: [bool; 254] = modulus_le_bits().as_array();
            assert(!p_plus_4_bits[2]);
            p_plus_4_bits[2] = true;

            let p_plus_4 = from_le_bits::<254>(p_plus_4_bits);
            assert_eq(p_plus_4, 4);

            // checking that converting p_plus_4 to 254 LE bits produces the same
            // bit set to 1 as p_plus_4_bits and otherwise zeroes
            let mut p_plus_4_converted_bits: [bool; 254] = p_plus_4.to_le_bits();
            assert(p_plus_4_converted_bits[2]);
            p_plus_4_converted_bits[2] = false;
            assert_eq(p_plus_4_converted_bits, [false; 254]);

            // checking that Field::from_le_bits::<254> on the Field modulus produces 0
            assert_eq(modulus_le_bits().len(), 254);
            let p = from_le_bits::<254>(modulus_le_bits().as_array());
            assert_eq(p, 0);

            // checking that converting 0 to 254 LE bits produces 254 false values
            let p_bits: [bool; 254] = 0.to_le_bits();
            assert_eq(p_bits, [false; 254]);
        }
    }

    #[test(should_fail_with = "call to assert_max_bit_size")]
    fn max_bit_size_too_large() {
        let x: Field = 0x010000;
        x.assert_max_bit_size::<16>();
    }

}

53.source:
// poseidon-iso variant, age verification (online alcohol sale): the holder is at least `threshold` years old
// today, from birth_date (a CBOR full-date).
// The Poseidon digest of the private IssuerSignedItemBytes, as issued, is checked against the public
// digest (as the MSO stores it in valueDigests); the item is then parsed (../../common/lib) and the
// predicate is checked on the elementValue it holds.
use iso::{
    decode_digest, decode_text, field_from_be_bytes, item_value, MAX_UINT_LEN, parse_item,
    predicates,
};
use iso_poseidon::poseidon_item_digest;

global N: u32 = 128; // maximum size of IssuerSignedItemBytes
global V: u32 = 14; // maximum size of the elementValue

fn main(
    element_id_cbor: pub [u8; 11], // CBOR text string "birth_date"
    hash_cbor: pub [u8; 34], // CBOR byte string, as in valueDigests
    today_cbor: pub [u8; 14], // CBOR full-date: D9 03 EC 6A <YYYY-MM-DD>
    threshold_cbor: pub [u8; MAX_UINT_LEN], // CBOR unsigned integer, zero-padded
    item: [u8; N], // IssuerSignedItemBytes as issued, zero-padded
    item_len: u32,
) {
    let hash: [u8; 32] = decode_digest(hash_cbor);
    assert(
        poseidon_item_digest(item, item_len) == field_from_be_bytes(hash),
        "Hash verification has failed",
    );
    let element_id: [u8; 10] = decode_text(element_id_cbor);
    let parsed = parse_item(item, item_len, element_id);
    let value: [u8; V] = item_value(item, parsed);
    let value_len = parsed.value_len;
    predicates::age(value, value_len, today_cbor, threshold_cbor);
}

55.source:
use std::hash::sha256_compression;

pub mod cbor;
pub mod predicates;

// ISO/IEC 18013-5 (9.1.2.4): the MSO digest of a data element is
//   h = H(IssuerSignedItemBytes), IssuerSignedItemBytes = #6.24(bstr .cbor IssuerSignedItem)
//   IssuerSignedItem = { "digestID": uint, "random": bstr, "elementIdentifier": tstr, "elementValue": any }
// The standard fixes neither the order of the four entries nor the length of random beyond a
// 16-byte minimum, and h is over the bytes exactly as the issuer encoded them. The circuits
// therefore receive IssuerSignedItemBytes as issued and parse it (parse_item): the four entries in
// any order, a random of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes, and items of up to 65535 bytes.
// The standard allows H = SHA-256, SHA-384 or SHA-512; SHA-512 is in ../sha512, and
// ../poseidon applies Poseidon to the same bytes for comparison, which no ISO issuer produces.

// A CBOR uint (digestID or an integer elementValue) takes at most 9 bytes
pub global MAX_UINT_LEN: u32 = 9;
pub global MIN_RANDOM_LEN: u32 = 16; // the minimum allowed by the standard
pub global MAX_RANDOM_LEN: u32 = 32;

// The four keys of IssuerSignedItem as CBOR text strings, each with a distinct first byte
global KEY_DIGEST_ID: [u8; 9] = [0x68, 0x64, 0x69, 0x67, 0x65, 0x73, 0x74, 0x49, 0x44];
global KEY_RANDOM: [u8; 7] = [0x66, 0x72, 0x61, 0x6e, 0x64, 0x6f, 0x6d];
global KEY_ELEMENT_ID: [u8; 18] = [
    0x71, 0x65, 0x6c, 0x65, 0x6d, 0x65, 0x6e, 0x74, 0x49, 0x64, 0x65, 0x6e, 0x74, 0x69, 0x66, 0x69,
    0x65, 0x72,
];
global KEY_VALUE: [u8; 13] =
    [0x6c, 0x65, 0x6c, 0x65, 0x6d, 0x65, 0x6e, 0x74, 0x56, 0x61, 0x6c, 0x75, 0x65];

// Decodes the CBOR unsigned integer (major type 0) at the start of field, in any of its encodings
// (1, 2, 3, 5 or 9 bytes, preferred or not; bytes after it are ignored). Returns the value, its
// encoded length and one-hot flags for the lengths 1, 2, 3, 5 and 9.
pub fn decode_uint<let N: u32>(field: [u8; N]) -> (u64, u32, [bool; 5]) {
    assert(N >= MAX_UINT_LEN);
    let b0 = field[0];
    assert(b0 >> 5 == 0, "Not a CBOR unsigned integer");
    let ai = b0 & 0x1f;
    let flags = [ai < 24, ai == 24, ai == 25, ai == 26, ai == 27];
    let lens = [1, 2, 3, 5, 9];
    let mut len = 0;
    for s in 0..5 {
        len += flags[s] as u32 * lens[s];
    }
    assert(len != 0, "Invalid CBOR integer head");
    // big-endian argument after the head, selected by length
    let mut v: Field = ai as Field;
    let mut arg: Field = 0;
    for i in 1..MAX_UINT_LEN {
        arg = arg * 256 + field[i] as Field;
        for s in 1..5 {
            if i == lens[s] - 1 {
                v += flags[s] as Field * (arg - ai as Field);
            }
        }
    }
    (v as u64, len, flags)
}

// Decodes the CBOR full-date (RFC 8943) at cbor[off..], tag 1004 over a 10-byte text string
// "YYYY-MM-DD", i.e. D9 03 EC 6A <date>, as the number YYYYMMDD
pub fn decode_full_date<let N: u32>(cbor: [u8; N], off: u32) -> u32 {
    let prefix = [0xD9, 0x03, 0xEC, 0x6A];
    for i in 0..4 {
        assert(cbor[off + i] == prefix[i], "Not a CBOR full-date");
    }
    assert((cbor[off + 8] == 45) & (cbor[off + 11] == 45), "Not a YYYY-MM-DD date");
    let mut date: u32 = 0;
    for i in [4, 5, 6, 7, 9, 10, 12, 13] {
        let c = cbor[off + i];
        assert((c >= 48) & (c <= 57), "Not a YYYY-MM-DD date");
        date = date * 10 + (c - 48) as u32;
    }
    date
}

// Decodes cbor, which must be exactly a CBOR text string of N < 24 bytes (head 0x60 + N)
pub fn decode_text<let N: u32, let M: u32>(cbor: [u8; M]) -> [u8; N] {
    assert(N < 24);
    assert(M == N + 1);
    assert(cbor[0] == 0x60 + N as u8, "Not a CBOR text string of the expected length");
    let mut out = [0; N];
    for i in 0..N {
        out[i] = cbor[1 + i];
    }
    out
}

// Decodes a digest as the MSO stores it in valueDigests: cbor must be exactly a CBOR byte string
// of N bytes, 24 <= N < 256 (head 58 NN)
pub fn decode_digest<let N: u32, let M: u32>(cbor: [u8; M]) -> [u8; N] {
    assert((N >= 24) & (N < 256));
    assert(M == N + 2);
    assert((cbor[0] == 0x58) & (cbor[1] == N as u8), "Not a CBOR byte string of the digest length");
    let mut out = [0; N];
    for i in 0..N {
        out[i] = cbor[2 + i];
    }
    out
}

// The parsed IssuerSignedItemBytes: the digestID, and where the elementValue is in the item.
pub struct Item {
    pub digest_id: u64,
    pub value_off: u32,
    pub value_len: u32,
}

// Size of the CBOR data item at buf[off..], computed outside the circuit (a hint)
unconstrained fn cbor_item_len<let N: u32>(buf: [u8; N], off: u32) -> u32 {
    let mut pos = off;
    let mut left: u32 = 1;
    for _ in 0..N {
        if (left != 0) & (pos + 2 < N) {
            let b = buf[pos] as u32;
            let (major, ai) = (b / 32, b % 32);
            let (arg, head) = if ai < 24 {
                (ai, 1)
            } else if ai == 24 {
                (buf[pos + 1] as u32, 2)
            } else if ai == 25 {
                (buf[pos + 1] as u32 * 256 + buf[pos + 2] as u32, 3)
            } else if ai == 26 {
                (0, 5)
            } else {
                (0, 9)
            };
            left -= 1;
            pos += head;
            if (major == 2) | (major == 3) {
                pos += arg;
            }
            if major == 4 {
                left += arg;
            }
            if major == 5 {
                left += 2 * arg;
            }
            if major == 6 {
                left += 1;
            }
        }
    }
    pos - off
}

// Offsets of the four entries (digestID, random, elementIdentifier, elementValue), their order in
// the item, and the length of the elementValue, computed outside the circuit (a hint)
unconstrained fn item_layout<let N: u32>(item: [u8; N], first: u32) -> ([u32; 4], [u32; 4], u32) {
    let mut offs = [0; 4];
    let mut order = [0; 4];
    let mut value_len = 0;
    let mut pos = first;
    for j in 0..4 {
        if pos < N {
            let b = item[pos];
            let k = if b == KEY_DIGEST_ID[0] {
                0
            } else if b == KEY_RANDOM[0] {
                1
            } else if b == KEY_ELEMENT_ID[0] {
                2
            } else {
                3
            };
            let key_len = [9, 7, 18, 13][k];
            offs[k] = pos;
            order[j] = k;
            let len = cbor_item_len(item, pos + key_len);
            if k == 3 {
                value_len = len;
            }
            pos += key_len + len;
        }
    }
    (offs, order, value_len)
}

// Parses IssuerSignedItemBytes, item[0..len], as issued: #6.24(bstr) over a map of the four
// entries in any order, with the elementIdentifier `element_id` (a text string shorter than 24
// bytes). Checks the tag and bstr head, the map head, each key, digestID (a CBOR uint), random (a
// bstr of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes) and the elementIdentifier, and that the entries
// are contiguous and fill the map. The elementValue is what remains; the caller checks that
// item[value_off..value_off + value_len] is exactly one CBOR item of the expected type, which makes
// the split of the item into entries unique.
pub fn parse_item<let N: u32, let E: u32>(item: [u8; N], len: u32, element_id: [u8; E]) -> Item {
    assert(E < 24);
    assert(len <= N, "IssuerSignedItemBytes exceeds the maximum size");
    // reads past the item (within the bound) are zeros
    let mut buf: [u8; N + 64] = [0; N + 64];
    for i in 0..N {
        buf[i] = item[i];
    }
    // D8 18, then the bstr head: 58 LL or 59 LL LL
    assert((buf[0] == 0xD8) & (buf[1] == 0x18), "Not IssuerSignedItemBytes (#6.24)");
    let short = buf[2] == 0x58;
    assert(short | (buf[2] == 0x59), "Not IssuerSignedItemBytes (bstr head)");
    let first = if short { 5 } else { 6 };
    let inner = if short {
        buf[3] as u32
    } else {
        buf[3] as u32 * 256 + buf[4] as u32
    };
    assert(inner == len - (first - 1), "IssuerSignedItemBytes length mismatch");
    assert(buf[first - 1] == 0xA4, "IssuerSignedItem is not a map of 4 entries");

    // Safety: the offsets, order and value length are checked below
    let (offs, order, value_len) = unsafe { item_layout(buf, first) };

    // the keys
    for k in 0..9 {
        assert(buf[offs[0] + k] == KEY_DIGEST_ID[k], "Invalid digestID key");
    }
    for k in 0..7 {
        assert(buf[offs[1] + k] == KEY_RANDOM[k], "Invalid random key");
    }
    for k in 0..18 {
        assert(buf[offs[2] + k] == KEY_ELEMENT_ID[k], "Invalid elementIdentifier key");
    }
    for k in 0..13 {
        assert(buf[offs[3] + k] == KEY_VALUE[k], "Invalid elementValue key");
    }
    // digestID: a CBOR uint
    let mut id_bytes = [0; MAX_UINT_LEN];
    for k in 0..MAX_UINT_LEN {
        id_bytes[k] = buf[offs[0] + 9 + k];
    }
    let (digest_id, id_len, _) = decode_uint(id_bytes);
    // random: a bstr of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes, head 40+n (n < 24) or 58 n
    let rh = buf[offs[1] + 7];
    let r_short = (rh >= 0x40) & (rh < 0x58);
    assert(r_short | (rh == 0x58), "random is not a CBOR byte string");
    let r_len = if r_short {
        (rh - 0x40) as u32
    } else {
        buf[offs[1] + 8] as u32
    };
    assert(
        (r_len >= MIN_RANDOM_LEN) & (r_len <= MAX_RANDOM_LEN),
        "random has an unsupported length",
    );
    let r_head = if r_short { 1 } else { 2 };
    // elementIdentifier: the text string element_id
    assert(buf[offs[2] + 18] == 0x60 + E as u8, "Wrong elementIdentifier");
    for k in 0..E {
        assert(buf[offs[2] + 19 + k] == element_id[k], "Wrong elementIdentifier");
    }
    // the entries in the hinted order are contiguous and fill the map
    let seg = [9 + id_len, 7 + r_head + r_len, 19 + E, 13 + value_len];
    for i in 0..4 {
        assert(order[i] < 4, "Invalid entry order");
        for j in 0..i {
            assert(order[i] != order[j], "Invalid entry order");
        }
    }
    let mut pos = first;
    for j in 0..4 {
        assert(offs[order[j]] == pos, "IssuerSignedItem entries are not contiguous");
        pos += seg[order[j]];
    }
    assert(pos == len, "IssuerSignedItem entries do not fill the item");
    Item { digest_id, value_off: offs[3] + 13, value_len }
}

// The elementValue of a parsed item as an array of V bytes (zeros after value_len)
pub fn item_value<let N: u32, let V: u32>(item: [u8; N], parsed: Item) -> [u8; V] {
    assert(parsed.value_len <= V, "elementValue exceeds the maximum size");
    let mut buf: [u8; N + V] = [0; N + V];
    for i in 0..N {
        buf[i] = item[i];
    }
    let mut out = [0; V];
    for i in 0..V {
        out[i] = (i < parsed.value_len) as u8 * buf[parsed.value_off + i];
    }
    out
}

// item[0..len] followed by the byte `marker` (0x80 for SHA-2 padding) and zeros
pub fn item_message<let N: u32>(item: [u8; N], len: u32, marker: Field) -> [Field; N + 1] {
    let mut msg = [0; N + 1];
    for i in 0..N {
        msg[i] = (i < len) as Field * item[i] as Field;
    }
    for i in 0..(N + 1) {
        msg[i] += (i == len) as Field * marker;
    }
    msg
}

// Merkle-Damgard padding: copies msg (which already holds the 0x80 byte) into BLOCKS blocks of
// B bytes and writes the length in bits into the last 8 bytes of the block where the message
// ends, given that the length field takes L bytes. Returns the padded message and a flag
// marking that last block.
pub fn md_pad<let N: u32, let B: u32, let L: u32, let BLOCKS: u32>(
    msg: [Field; N],
    len: u32,
) -> ([Field; B * BLOCKS], [bool; BLOCKS]) {
    assert(N <= B * BLOCKS);
    let mut padded = [0; B * BLOCKS];
    for i in 0..N {
        padded[i] = msg[i];
    }
    let bit_len: [u8; 8] = ((len * 8) as Field).to_be_bytes();
    let mut last = [false; BLOCKS];
    for b in 0..BLOCKS {
        last[b] = (len + 1 + L > B * b) & (len + 1 + L <= B * (b + 1));
        for j in 0..8 {
            padded[B * b + B - 8 + j] += last[b] as Field * bit_len[j] as Field;
        }
    }
    (padded, last)
}

// SHA-256(item[0..len]), hashing the padded item block by block
pub fn sha256_item_digest<let N: u32>(item: [u8; N], len: u32) -> [u8; 32] {
    let (msg, last): ([Field; 64 * ((N + 1 + 8 + 63) / 64)], [bool; (N + 1 + 8 + 63) / 64]) =
        md_pad::<_, 64, 8, _>(item_message(item, len, 0x80), len);

    let mut state: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let mut digest_state = [0; 8];
    for b in 0..last.len() {
        let mut words = [0; 16];
        for w in 0..16 {
            let mut word = 0;
            for j in 0..4 {
                word = word * 256 + msg[64 * b + 4 * w + j];
            }
            words[w] = word as u32;
        }
        state = sha256_compression(words, state);
        for w in 0..8 {
            digest_state[w] += last[b] as Field * state[w] as Field;
        }
    }
    let mut out = [0; 32];
    for w in 0..8 {
        let bytes: [u8; 4] = digest_state[w].to_be_bytes();
        for j in 0..4 {
            out[4 * w + j] = bytes[j];
        }
    }
    out
}

// A 32-byte big-endian public input as a Field
pub fn field_from_be_bytes(bytes: [u8; 32]) -> Field {
    let mut f = 0;
    for i in 0..32 {
        f = f * 256 + bytes[i] as Field;
    }
    f
}

56.source:
// The predicates of the four test scenarios, shared by every variant. Each takes the
// elementValue exactly as the issuer encoded it (value[0..value_len], zero-padded to V bytes),
// checks that it is exactly one CBOR item of the element's type, and checks the predicate against
// the CBOR-encoded public parameters.
//
//   age        birth_date (full-date)              the holder is at least `threshold` years old today
//   rental     driving_privileges (array of maps)  a privilege of `category` issued on or before
//                                                  `held_since` and expiring on or after `return_date`
//   residence  resident_postal_code (text string)  the 5-digit ZIP code (ZIP or ZIP+4) is in
//                                                  [zip_min, zip_max]
//   veteran    veteran (uint, AAMVA namespace)      the value is 1
use crate::{cbor, decode_full_date, decode_uint, MAX_UINT_LEN};

// Maximum number of CBOR tokens of a driving_privileges value
pub global RENTAL_TOKENS: u32 = 64;

// birth_date: the holder turned `threshold` on or before today. Dates as YYYYMMDD: the holder is
// at least t years old iff birth + t * 10000 <= today.
pub fn age<let V: u32>(
    value: [u8; V],
    value_len: u32,
    today_cbor: [u8; 14],
    threshold_cbor: [u8; MAX_UINT_LEN],
) {
    assert(value_len == 14, "birth_date is not a CBOR full-date");
    let birth = decode_full_date(value, 0);
    let today = decode_full_date(today_cbor, 0);
    let (threshold, _, _) = decode_uint(threshold_cbor);
    assert(threshold < 200, "Invalid age threshold");
    assert(birth + threshold as u32 * 10000 <= today, "Age verification has failed");
}

// veteran: the uint 1
pub fn veteran<let V: u32>(value: [u8; V], value_len: u32) {
    let (v, len, _) = decode_uint(value);
    assert(len == value_len, "veteran is not a CBOR unsigned integer");
    assert(v == 1, "Veteran verification has failed");
}

// A 5-digit ASCII number at s[off..off + 5]
fn five_digits<let N: u32>(s: [u8; N], off: u32) -> u32 {
    let mut n: u32 = 0;
    for i in 0..5 {
        let c = s[off + i];
        assert((c >= 48) & (c <= 57), "Not a ZIP code");
        n = n * 10 + (c - 48) as u32;
    }
    n
}

// resident_postal_code: a text string holding a US ZIP code, "NNNNN" or ZIP+4 "NNNNN-NNNN", whose
// 5-digit ZIP is within [zip_min, zip_max] (each a 5-character text string)
pub fn residence<let V: u32>(
    value: [u8; V],
    value_len: u32,
    zip_min_cbor: [u8; 6],
    zip_max_cbor: [u8; 6],
) {
    assert(V >= 11);
    let n = value_len - 1;
    assert(value[0] == 0x60 + n as u8, "resident_postal_code is not a CBOR text string");
    assert((n == 5) | (n == 10), "Not a US ZIP code");
    let zip = five_digits(value, 1);
    if n == 10 {
        assert(value[6] == 45, "Not a US ZIP+4 code");
        for i in 7..11 {
            assert((value[i] >= 48) & (value[i] <= 57), "Not a US ZIP+4 code");
        }
    }
    assert((zip_min_cbor[0] == 0x65) & (zip_max_cbor[0] == 0x65), "Invalid ZIP range");
    let lo = five_digits(zip_min_cbor, 1);
    let hi = five_digits(zip_max_cbor, 1);
    assert((lo <= zip) & (zip <= hi), "Residence verification has failed");
}

// Keys of a DrivingPrivilege (ISO/IEC 18013-5 7.2.4) as CBOR text strings
global KEY_CATEGORY: [u8; 22] = [
    0x75, 0x76, 0x65, 0x68, 0x69, 0x63, 0x6c, 0x65, 0x5f, 0x63, 0x61, 0x74, 0x65, 0x67, 0x6f, 0x72,
    0x79, 0x5f, 0x63, 0x6f, 0x64, 0x65,
]; // "vehicle_category_code"
global KEY_ISSUE: [u8; 11] = [0x6a, 0x69, 0x73, 0x73, 0x75, 0x65, 0x5f, 0x64, 0x61, 0x74, 0x65]; // "issue_date"
global KEY_EXPIRY: [u8; 12] =
    [0x6b, 0x65, 0x78, 0x70, 0x69, 0x72, 0x79, 0x5f, 0x64, 0x61, 0x74, 0x65]; // "expiry_date"

// Offsets of the vehicle_category_code, issue_date and expiry_date keys of the privilege of
// `category`, computed outside the circuit (a hint)
unconstrained fn find_privilege<let N: u32, let T: u32>(
    buf: [u8; N],
    toks: cbor::Tokens<T>,
    category: [u8; 4],
) -> (u32, u32, u32) {
    let mut found = (0, 0, 0);
    for j in 0..T {
        let off = toks.start[j];
        let mut is_cat = off + 26 < N;
        if is_cat {
            for k in 0..22 {
                is_cat &= buf[off + k] == KEY_CATEGORY[k];
            }
            let n = (category[0] - 0x60) as u32;
            for k in 0..4 {
                if k <= n {
                    is_cat &= buf[off + 22 + k] == category[k];
                }
            }
        }
        if is_cat & ((toks.rem[j] as u8) & 1 == 1) {
            let map = toks.par[j];
            let mut issue = 0;
            let mut expiry = 0;
            for i in 0..T {
                let o = toks.start[i];
                if (toks.par[i] == map) & (o + 12 < N) {
                    let mut is_issue = true;
                    for k in 0..11 {
                        is_issue &= buf[o + k] == KEY_ISSUE[k];
                    }
                    let mut is_expiry = true;
                    for k in 0..12 {
                        is_expiry &= buf[o + k] == KEY_EXPIRY[k];
                    }
                    if is_issue {
                        issue = o;
                    }
                    if is_expiry {
                        expiry = o;
                    }
                }
            }
            found = (off, issue, expiry);
        }
    }
    found
}

// driving_privileges: an array of DrivingPrivilege maps, one of which has vehicle_category_code
// `category` (a text string of 1 to 3 characters), issue_date <= held_since and
// expiry_date >= return_date. The value is parsed in the circuit (cbor::parse), so the three
// entries are keys of the same map, an element of the array, and the map's keys may be in any
// order and include others (e.g. codes).
pub fn rental<let V: u32>(
    value: [u8; V],
    value_len: u32,
    category_cbor: [u8; 4],
    held_since_cbor: [u8; 14],
    return_date_cbor: [u8; 14],
) {
    assert(value_len <= V, "driving_privileges exceeds the maximum size");
    let mut buf: [u8; V + 40] = [0; V + 40];
    for i in 0..V {
        buf[i] = value[i];
    }
    let toks: cbor::Tokens<RENTAL_TOKENS> = cbor::parse(buf, 0, value_len);
    assert(buf[0] >> 5 == 4, "driving_privileges is not an array");
    let n = category_cbor[0] - 0x60;
    assert((n >= 1) & (n <= 3), "Invalid vehicle category");

    // Safety: the offsets are checked below
    let (cat, issue, expiry) = unsafe { find_privilege(buf, toks, category_cbor) };
    let jc = toks.at(cat, "No privilege of the category");
    cbor::check_at(buf, cat, KEY_CATEGORY, "No privilege of the category");
    for k in 0..4 {
        if k <= n as u32 {
            assert(buf[cat + 22 + k] == category_cbor[k], "No privilege of the category");
        }
    }
    // the privilege map is an element of the array, and the three keys are its keys
    let map = toks.par[jc];
    let map_off = map as u32;
    let jm = toks.at(map_off, "Invalid driving privilege");
    assert((map_off != 0) & (toks.par[jm] == 0), "Invalid driving privilege");
    assert(buf[map_off] >> 5 == 5, "Invalid driving privilege");
    toks.assert_key_of(jc, map, "Invalid driving privilege");
    let ji = toks.at(issue, "The privilege has no issue_date");
    cbor::check_at(buf, issue, KEY_ISSUE, "The privilege has no issue_date");
    toks.assert_key_of(ji, map, "The privilege has no issue_date");
    let je = toks.at(expiry, "The privilege has no expiry_date");
    cbor::check_at(buf, expiry, KEY_EXPIRY, "The privilege has no expiry_date");
    toks.assert_key_of(je, map, "The privilege has no expiry_date");

    let issued = decode_full_date(buf, issue + 11);
    let expires = decode_full_date(buf, expiry + 12);
    assert(issued <= decode_full_date(held_since_cbor, 0), "Privilege held for too short a time");
    assert(expires >= decode_full_date(return_date_cbor, 0), "Privilege expires before the return");
}

57.source:
use iso::item_message;
use poseidon::poseidon::bn254::sponge;

// Poseidon is only a comparison here (no ISO issuer uses it): the item is zero-padded to
// 31 * POSEIDON_CHUNKS = 992 bytes, packed into big-endian chunks of 31 bytes (each below the
// BN254 modulus) and absorbed by the Poseidon sponge. The item encodes its own length, so the
// zero padding is unambiguous.
pub global POSEIDON_CHUNKS: u32 = 32;

pub fn poseidon_bytes<let N: u32>(item: [Field; N]) -> Field {
    assert(N <= 31 * POSEIDON_CHUNKS);
    let mut chunks = [0; POSEIDON_CHUNKS];
    for c in 0..POSEIDON_CHUNKS {
        for j in 0..31 {
            let i = 31 * c + j;
            chunks[c] = chunks[c] * 256 + if i < N { item[i] } else { 0 };
        }
    }
    sponge(chunks)
}

// Poseidon of item[0..len], an IssuerSignedItemBytes as issued
pub fn poseidon_item_digest<let N: u32>(item: [u8; N], len: u32) -> Field {
    poseidon_bytes(item_message(item, len, 0))
}

